// Build Job Bank search URLs
// Based on JobBankConnector.searchConfigs()
const searches = [
  { keyword: 'esthetician',  location: 'Ontario',          province: 'ON' },
  { keyword: 'hairstylist',  location: 'Ontario',          province: 'ON' },
  { keyword: 'esthetician',  location: 'New Brunswick',    province: 'NB' },
  { keyword: 'esthetician',  location: 'British Columbia', province: 'BC' },
  { keyword: 'makeup artist',location: 'Ontario',          province: 'ON' },
];

return searches.map(s => ({
  url: `https://www.jobbank.gc.ca/jobsearch/jobsearch?searchstring=${encodeURIComponent(s.keyword)}&locationstring=${encodeURIComponent(s.location)}&sort=D&action=search`,
  keyword: s.keyword,
  province: s.province,
}));

// Parse HTML into CanonicalJob objects
// Uses same logic as JobBankConnector
const html = $json.data;
const url  = $('HTTP: Fetch Job Bank Page').item.json.url;

// Load connector (in n8n: use require with node_modules or inline logic)
const crypto = require('crypto');

const BEAUTY_KEYWORDS = [
  'esthetician','esthéticienne','aesthetician',
  'hairstylist','coiffeuse','coiffeur',
  'makeup artist','make-up artist','maquilleuse',
  'nail technician','spa therapist','beautician',
  'skin care','soins esthétiques','salon','beauty',
];

function contentHash(title, company, location) {
  const content = [title, company, location].map(s => (s||'').toLowerCase().trim()).join('|');
  const hash = crypto.createHash('sha1').update('career-os-jobs|' + content).digest('hex');
  return [hash.slice(0,8), hash.slice(8,12), '5'+hash.slice(13,16),
    ((parseInt(hash.slice(16,18),16)&0x3f|0x80).toString(16)+hash.slice(18,20)),
    hash.slice(20,32)].join('-');
}

function isBeauty(text) {
  return BEAUTY_KEYWORDS.some(kw => (text||'').toLowerCase().includes(kw));
}

// Parse articles
const jobs = [];
const parts = html.split('<article');

for (let i = 1; i < parts.length; i++) {
  const part = parts[i];
  if (!part.includes('resultJobItem')) continue;

  const idMatch    = part.match(/data-id="(\d+)"/);
  const titleMatch = part.match(/<span class="noctitle"[^>]*>([^<]+)<\/span>/i);
  const compMatch  = part.match(/<span class="business"[^>]*>([^<]+)<\/span>/i);
  const locMatch   = part.match(/<span class="location"[^>]*>([^<]+)<\/span>/i);
  const salMatch   = part.match(/<span class="salary"[^>]*>([^<]+)<\/span>/i);
  const dateMatch  = part.match(/datetime="([^"]+)"/);

  if (!idMatch || !titleMatch) continue;

  const jobId   = idMatch[1];
  const title   = titleMatch[1].trim();
  const company = compMatch?.[1]?.trim() || '';
  const loc     = locMatch?.[1]?.trim() || '';
  const text    = [title, company, loc].join(' ');

  if (!isBeauty(text)) continue;

  jobs.push({
    external_id:     `JOBBANK_${jobId}`,
    source:          'jobbank',
    content_hash:    contentHash(title, company, loc),
    title,
    company_raw:     company,
    company_domain:  null,
    location_raw:    loc,
    city:            null,
    province:        null,
    country:         'CA',
    salary_raw:      salMatch?.[1]?.trim() || null,
    salary_min:      null,
    salary_max:      null,
    salary_currency: 'CAD',
    contract_type_raw: null,
    language_raw:    null,
    apply_url:       `https://www.jobbank.gc.ca/jobposting/${jobId}`,
    source_url:      `https://www.jobbank.gc.ca/jobposting/${jobId}`,
    raw_text:        [title, company, loc, salMatch?.[1]].filter(Boolean).join(' | '),
    raw_html:        null,
    posted_at:       dateMatch ? new Date(dateMatch[1]).toISOString() : null,
    fetched_at:      new Date().toISOString(),
  });
}

return jobs;
